      //   console.log(l, t);
      if (i === 0) {
        ctx.moveTo(l, t);
      } else {
        ctx.lineTo(l, t);
      }
    }
    // ctx.globalCompositeOperation = "destination-over";
    ctx.fillStyle = color;
    ctx.strokeStyle = "#fff";
    ctx.closePath();
    ctx.stroke();
    ctx.fill();
  }
}

