```javascript
export const post_data = function (url, data) {
  return new Promise(function (resolve, reject) {
    uni.request({
      url: url,
      method: "POST",
      header: {
        version_code: "2022011101",
        version_name: "V1.0.0",
        app_type: 5,
        channel: "miniprogram",
        user_id: "5",
        user_token: "1",
        "content-type": "application/x-www-form-urlencoded", //默认传输json格式，如果后台接收的不是json格式，需要加上
      },
      data: data,
      success(res) {
        // 如果成功，符合预期
        if (res.data.code == 0) {
          console.log(res);
          resolve(res.data.data);
        } else {
          // resolve(res.data)
          console.log(url, res.data.msg);
          uni.showToast({
            title: res.data.msg,
            duration: 2000,
            icon: "none",
          });
        }
      },
      fail() {
        console.log(url, "接口请求失败");
        reject();
      },
    });
  });
};
```

