```javascript
  nextTick(() => {
    document.querySelectorAll('table').forEach((table, idx) => {
      // 创建div容器并插入到表格后面
      const div = document.createElement('div')
      div.className = 'divTableContainer'
      // div.style.margin = '20px';
      // div.style.padding = '10px';
      // div.style.border = '1px solid #ddd';
